// Turns art/manifest.json into the module the scene mod imports.
// Run after replacing the art: node tools/build-manifest.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "mods", "x-mas-paper-scene");
const manifest = JSON.parse(readFileSync(join(root, "art", "manifest.json"), "utf8"));
const out = [
  "// Generated by tools/build-manifest.mjs from art/manifest.json. Do not edit.",
  `export const DENSITY = ${manifest.density};`,
  "// name -> { file, size: [w, h], anchor: [x, y], overlays? }, all in logical px.",
  `export const ASSETS = ${JSON.stringify(manifest.assets)};`,
  "",
].join("\n");
writeFileSync(join(root, "manifest.js"), out);
console.log(`manifest.js: ${Object.keys(manifest.assets).length} assets`);
